finition":{"id":"LUA002","languages":["lua"],"title":"Lua: динамическая команда io.popen","description":"Lua: динамическая команда io.popen. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-78","owasp":"A03:2021","confidence":"medium","pattern":"\\bio\\.popen\\s*\\(\\s*(?:[A-Za-z_]\\w*|[\"''][^\\n]*[\"'']\\s*\\.\\.)","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Исключите сборку команды из внешнего ввода; предпочитайте API без интерпретации shell.","references":["https://cwe.mitre.org/data/definitions/78.html","https://www.lua.org/manual/5.4/manual.html"]}},{"ruleId":"LUA003","contentHash":"0dc6ad66c906556035f09d34ac179eddff4482abd16ec5c1298bafbe13b0fc2b","definition":{"id":"LUA003","languages":["lua"],"title":"Lua: загрузка динамического кода","description":"Lua: загрузка динамического кода. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-95","owasp":"A03:2021","confidence":"medium","pattern":"\\b(?:load|loadstring)\\s*\\(\\s*[A-Za-z_]\\w*","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Разбирайте данные вместо загрузки кода; ограничение environment не делает недоверенный Lua-код безопасным.","references":["https://cwe.mitre.org/data/definitions/95.html","https://www.lua.org/manual/5.4/manual.html"]}},{"ruleId":"LUA004","contentHash":"ca943cbf854f8ca1b9f18de5a4223c3f336d170519c443f49ebd733cde2d8965","definition":{"id":"LUA004","languages":["lua"],"title":"Lua: SQL собирается конкатенацией","description":"Lua: SQL собирается конкатенацией. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-89","owasp":"A03:2021","confidence":"medium","pattern":"(?:\\:execute|\\.query)\\s*\\(\\s*[\"''][^\\n]*[\"'']\\s*\\.\\.","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Применяйте параметры запроса поддерживаемого драйвера вместо конкатенации SQL.","references":["https://cwe.mitre.org/data/definitions/89.html","https://www.lua.org/manual/5.4/manual.html"]}},{"ruleId":"LUA005","contentHash":"ab53d2d8db7c01ba34ac2f5c90ef0a3b725d3f3e5162769355eed2fd39f4191d","definition":{"id":"LUA005","languages":["lua"],"title":"Lua: HTML из параметров OpenResty","description":"Lua: HTML из параметров OpenResty. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"high","cwe":"CWE-79","owasp":"A03:2021","confidence":"medium","pattern":"\\bngx\\.(?:say|print)\\s*\\(\\s*ngx\\.var\\.arg_[A-Za-z_]\\w*","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"xss","recommendation":"Экранируйте HTML по контексту или отдавайте данные как JSON с соответствующим Content-Type.","references":["https://cwe.mitre.org/data/definitions/79.html","https://www.lua.org/manual/5.4/manual.html"]}},{"ruleId":"PS001","contentHash":"27b3847b079843b5e3194a486ae74dc8cf6efbf1961eb8f4368e63e85cfaef5e","definition":{"id":"PS001","languages":["powershell"],"title":"PowerShell: выполнение строки как кода","description":"PowerShell: выполнение строки как кода. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-95","owasp":"A03:2021","confidence":"medium","pattern":"\\b(?:Invoke-Expression|iex)\\b\\s+(?:-Command\\s+)?[^\\r\\n;]+","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Используйте прямой вызов команды и отдельные аргументы; не выполняйте строку из внешнего источника.","references":["https://cwe.mitre.org/data/definitions/95.html","https://learn.microsoft.com/en-us/powershell/scripting/security/preventing-script-injection"]}},{"ruleId":"PS002","contentHash":"1a5af62a14f33986856dbff297a3fddd0d56e273577e5b6480bea40c0ef6c19d","definition":{"id":"PS002","languages":["powershell"],"title":"PowerShell: отключена проверка TLS","description":"PowerShell: отключена проверка TLS. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"high","cwe":"CWE-295","owasp":"A02:2021","confidence":"medium","pattern":"\\b(?:Invoke-WebRequest|Invoke-RestMethod|iwr|irm)\\b[^\\r\\n;]*-SkipCertificateCheck\\b(?!\\s*:\\s*\\$false\\b)","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"line","category":"transport","recommendation":"Удалите SkipCertificateCheck и настройте доверенный CA и корректное имя сервера.","references":["https://cwe.mitre.org/data/definitions/295.html","https://learn.microsoft.com/en-us/powershell/scripting/security/preventing-script-injection"]}},{"ruleId":"PS003","contentHash":"7e606535c1447d8f02a1af76693663dd4a4c33ca78d21530f39af2eaf254ae4c","definition":{"id":"PS003","languages":["powershell"],"title":"PowerShell: пароль в открытом строковом литерале","description":"PowerShell: пароль в открытом строковом литерале. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-798","owasp":"A07:2021","confidence":"medium","pattern":"\\bConvertTo-SecureString\\b\\s+(?:-String\\s+)?[\"''][^\"''\\r\\n]{6,}[\"''][^\\r\\n;]*-AsPlainText\\b","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"line","category":"secrets","recommendation":"Получайте секрет через Read-Host -AsSecureString или хранилище секретов; удалите литерал и смените раскрытый пароль.","references":["https://cwe.mitre.org/data/definitions/798.html","https://learn.microsoft.com/en-us/powershell/scripting/security/preventing-script-injection"]}},{"ruleId":"PS004","contentHash":"36e5bf3e3c0e8a81c33843079588269c2cfc29498d629c4be7dce749da68aec5","definition":{"id":"PS004","languages":["powershell"],"title":"PowerShell: безусловный callback сертификата","description":"PowerShell: безусловный callback сертификата. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"high","cwe":"CWE-295","owasp":"A02:2021","confidence":"medium","pattern":"\\bServerCertificateValidationCallback\\s*=\\s*\\{\\s*\\$true\\s*\\}","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"line","category":"transport","recommendation":"Сохраняйте штатную проверку TLS и настройте доверенный CA вместо безусловного callback.","references":["https://cwe.mitre.org/data/definitions/295.html","https://learn.microsoft.com/en-us/powershell/scripting/security/preventing-script-injection"]}},{"ruleId":"PS005","contentHash":"78029eb7432ff59815629b3926d10da7f59b1a5ec5f600e69ecbd379f36bc748","definition":{"id":"PS005","languages":["powershell"],"title":"PowerShell: интерполяция в SQL-команде","description":"PowerShell: интерполяция в SQL-команде. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-89","owasp":"A03:2021","confidence":"medium","pattern":"\\bCommandText\\s*=\\s*\"[^\"\\r\\n]*\\$(?:[A-Za-z_]\\w*|\\{)","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Используйте фиксированный CommandText и SqlParameter вместо интерполяции SQL.","references":["https://cwe.mitre.org/data/definitions/89.html","https://learn.microsoft.com/en-us/powershell/scripting/security/preventing-script-injection"]}},{"ruleId":"NEWSEC001","contentHash":"2fef699630fbc75da4127a1a1860017c41df7cb6f1d1eef1532c2f94ede12925","definition":{"id":"NEWSEC001","languages":["c","cpp","dart","elixir","lua","powershell"],"title":"Секрет в исходном коде","description":"Секрет в исходном коде. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-798","owasp":"A07:2021","confidence":"medium","pattern":"\\b(?:password|passwd|secret|api[_-]?key|access[_-]?token)\\s*[:=]\\s*[\"''][^\"''\\r\\n]{6,}[\"'']","patternFlags":"i","exclude":"(?:example|sample|placeholder|changeme|your[_-]|\\$\\{|\\*{3,})","excludeFlags":"i","scope":"line","category":"secrets","recommendation":"Удалите секрет из кода, отзовите его и загружайте новое значение из защищённого хранилища.","references":["https://cwe.mitre.org/data/definitions/798.html"]}},{"ruleId":"NEWSEC002","contentHash":"f1d8ffbaa816c8c8e07423e1b260f25b2e6648c47f296ee3460b0eefd9db1a0c","definition":{"id":"NEWSEC002","languages":["c","cpp","dart","elixir","lua","powershell"],"title":"Приватный ключ в исходном коде","description":"Приватный ключ в исходном коде. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-321","owasp":"A07:2021","confidence":"medium","pattern":"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"secrets","recommendation":"Удалите и перевыпустите ключ; храните его вне репозитория с минимальными правами доступа.","references":["https://cwe.mitre.org/data/definitions/321.html"]}},{"ruleId":"NEWSEC003","contentHash":"527175dd206f000ec34040f1de7bb657d44e0f22f2a6dfb3f3dd5ae94b0534c6","definition":{"id":"NEWSEC003","languages":["c","cpp","dart","elixir","lua","powershell"],"title":"AWS access key в исходном коде","description":"AWS access key в исходном коде. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-798","owasp":"A07:2021","confidence":"medium","pattern":"\\b(?:AKIA|ASIA)[A-Z0-9]{16}\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"secrets","recommendation":"Проверьте использование и отзовите ключ AWS; используйте IAM role или защищённое хранилище.","references":["https://cwe.mitre.org/data/definitions/798.html"]}},{"ruleId":"NEWSEC004","contentHash":"ced85e94e5af0cd26588ba0fdddeaf8bc6f4566132c5ec016fe5d74f5244531d","definition":{"id":"NEWSEC004","languages":["c","cpp","dart","elixir","lua","powershell"],"title":"GitHub token в исходном коде","description":"GitHub token в исходном коде. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-798","owasp":"A07:2021","confidence":"medium","pattern":"\\bgh[pousr]_[A-Za-z0-9]{36,255}\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"secrets","recommendation":"Отзовите токен GitHub, проверьте доступ и выдайте минимальные permissions новому токену.","references":["https://cwe.mitre.org/data/definitions/798.html"]}},{"ruleId":"NEWSEC005","contentHash":"ba6fa45b3e5f95d6741aec649855ed0919e830e48d9075166f94a0c362a20de2","definition":{"id":"NEWSEC005","languages":["c","cpp","dart","elixir","lua","powershell"],"title":"GitLab token в исходном коде","description":"GitLab token в исходном коде. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-798","owasp":"A07:2021","confidence":"medium","pattern":"\\bglpat-[A-Za-z0-9_-]{20,255}\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"secrets","recommendation":"Отзовите токен GitLab и проверьте операции с репозиториями.","references":["https://cwe.mitre.org/data/definitions/798.html"]}},{"ruleId":"NEWSEC006","contentHash":"fe0f0e3c348557164217d081fafa5c1292f17a3e1e7265fe8b79d68041134937","definition":{"id":"NEWSEC006","languages":["c","cpp","dart","elixir","lua","powershell"],"title":"Пароль в URI базы данных","description":"Пароль в URI базы данных. Проверьте доверие к данным и условия использования; сигнатура не доказывает эксплуатацию.","severity":"critical","cwe":"CWE-798","owasp":"A07:2021","confidence":"medium","pattern":"\\b(?:postgres(?:ql)?|mysql|mongodb(?:\\+srv)?):\\/\\/[^\\s:@/]+:[^\\s@/]+@","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"line","category":"secrets","recommendation":"Уберите пароль из исходников и смените его; загружайте URI подключения из хранилища секретов.","references":["https://cwe.mitre.org/data/definitions/798.html"]}}]'::jsonb)
WITH ORDINALITY AS data(entry, ordinality);

INSERT INTO sast_rules.rules (id, title, languages, category, cwe, owasp)
SELECT rule_id, definition->>'title', definition->'languages',
       definition->>'category', definition->>'cwe', definition->>'owasp'
FROM sast_rule_extension ON CONFLICT (id) DO NOTHING;

INSERT INTO sast_rules.rule_versions (rule_id, content_hash, definition)
SELECT rule_id, content_hash, definition FROM sast_rule_extension
ON CONFLICT (rule_id, content_hash) DO NOTHING;

INSERT INTO sast_rules.rulesets (name, source, content_hash, rule_count)
VALUES ('builtin-150036-720c78f1807a', 'builtin', '720c78f1807ad957abd41b1ee1dc0a211a29d533df3e4d35de6b9a9ccc84cdae', 150036)
ON CONFLICT (content_hash) DO NOTHING;

INSERT INTO sast_rules.ruleset_items (ruleset_id, rule_id, rule_version_id, position)
SELECT next.id, item.rule_id, item.rule_version_id, item.position
FROM sast_rules.ruleset_items item
JOIN sast_rules.rulesets parent ON parent.id = item.ruleset_id
CROSS JOIN sast_rules.rulesets next
WHERE parent.content_hash = '5a38c220111a6ea2483a39f15a53c49c668c74aba3d61fa9c6e3419160a842c9' AND next.content_hash = '720c78f1807ad957abd41b1ee1dc0a211a29d533df3e4d35de6b9a9ccc84cdae'
UNION ALL
SELECT next.id, seed.rule_id, version.id, seed.position
FROM sast_rule_extension seed
JOIN sast_rules.rule_versions version
  ON version.rule_id = seed.rule_id AND version.content_hash = seed.content_hash
CROSS JOIN sast_rules.rulesets next
WHERE next.content_hash = '720c78f1807ad957abd41b1ee1dc0a211a29d533df3e4d35de6b9a9ccc84cdae'
ON CONFLICT (ruleset_id, rule_id) DO NOTHING;

DO $verify_extension$
BEGIN
  IF (SELECT count(*) FROM sast_rules.ruleset_items item
      JOIN sast_rules.rulesets ruleset ON ruleset.id = item.ruleset_id
      WHERE ruleset.content_hash = '720c78f1807ad957abd41b1ee1dc0a211a29d533df3e4d35de6b9a9ccc84cdae') <> 150036
     OR NOT EXISTS (SELECT 1 FROM sast_rules.rulesets
                    WHERE content_hash = '720c78f1807ad957abd41b1ee1dc0a211a29d533df3e4d35de6b9a9ccc84cdae' AND rule_count = 150036)
     OR EXISTS (
       SELECT 1 FROM sast_rules.ruleset_items original
       JOIN sast_rules.rulesets parent ON parent.id = original.ruleset_id
       LEFT JOIN sast_rules.ruleset_items copied
         ON copied.ruleset_id = (SELECT id FROM sast_rules.rulesets WHERE content_hash = '720c78f1807ad957abd41b1ee1dc0a211a29d533df3e4d35de6b9a9ccc84cdae')
         AND copied.rule_id = original.rule_id
       WHERE parent.content_hash = '5a38c220111a6ea2483a39f15a53c49c668c74aba3d61fa9c6e3419160a842c9'
         AND (copied.rule_version_id IS DISTINCT FROM original.rule_version_id
              OR copied.position IS DISTINCT FROM original.position)
     )
     OR EXISTS (
       SELECT 1 FROM sast_rule_extension seed
       LEFT JOIN sast_rules.rule_versions version
         ON version.rule_id = seed.rule_id AND version.content_hash = seed.content_hash
       LEFT JOIN sast_rules.ruleset_items item
         ON item.rule_version_id = version.id AND item.rule_id = seed.rule_id
         AND item.ruleset_id = (SELECT id FROM sast_rules.rulesets WHERE content_hash = '720c78f1807ad957abd41b1ee1dc0a211a29d533df3e4d35de6b9a9ccc84cdae')
       WHERE version.definition IS DISTINCT FROM seed.definition
          OR item.position IS DISTINCT FROM seed.position
     ) THEN
    RAISE EXCEPTION 'Extended SAST catalog does not match the built-in snapshot';
  END IF;
END
$verify_extension$;
